def _scan_paper_workflow_status(root: Path, decision_date: str) -> list[dict[str, Any]]:
    records = []
    for metadata_path in _metadata_paths(root, "metadata.json"):
        metadata = _load_json_or_none(metadata_path)
        if metadata is None or not metadata.get("workflow_status_id"):
            continue
        metadata_date = _date_string(metadata.get("latest_decision_date"))
        if decision_date and metadata_date and metadata_date != decision_date:
            continue
        output_files = _output_files(metadata)
        component_statuses = metadata.get("component_statuses") if isinstance(metadata.get("component_statuses"), dict) else {}
        count_source = metadata if any(key in metadata for key in _actionability_count_keys()) else component_statuses
        records.append(
            _record(
                workflow_area="PAPER_TRADING",
                component="PAPER_WORKFLOW_STATUS",
                status=_string_or_empty(metadata.get("status")) or "READY",
                stage=_string_or_empty(metadata.get("workflow_stage")) or "PAPER_WORKFLOW_READY",
                latest_artifact_id=_string_or_empty(metadata.get("workflow_status_id")) or metadata_path.parent.name,
                decision_date=metadata_date,
                report_path=output_files.get("paper_workflow_status_report", metadata_path.parent / "paper_workflow_status_report.md"),
                metadata_path=metadata_path,
                warning_count=len(metadata.get("warnings", [])) if isinstance(metadata.get("warnings"), list) else 0,
                total_warning_count=_int_or_zero(count_source.get("total_warning_count")),
                expected_demo_warning_count=_int_or_zero(count_source.get("expected_demo_warning_count")),
                stale_warning_count=_int_or_zero(count_source.get("stale_warning_count")),
                actionable_warning_count=_int_or_zero(count_source.get("actionable_warning_count")),
                blocking_error_count=_int_or_zero(count_source.get("blocking_error_count")),
                notes=f"next_manual_action={_string_or_empty(metadata.get('next_manual_action'))}",
                created_at=_created_at_or_artifact_mtime(metadata_path, metadata),
            )
        )
    return records


def _created_at_or_artifact_mtime(metadata_path: Path, metadata: dict[str, Any]) -> str:
    created_at = _string_or_empty(metadata.get("created_at"))
    if created_at and not created_at.startswith("1970-01-01T00:00:00"):
        return created_at
    try:
        return f"mtime:{metadata_path.stat().st_mtime_ns:020d}"
    except OSError:
        return created_at


def _health_records(
    root: Path,
    *,
    workflow_area: str,
    component: str,
    id_key: str,
    report_key: str,
    default_report: str,
    stage: str,
) -> list[dict[str, Any]]:
    records = []
    for metadata_path in _metadata_paths(root, "metadata.json"):
        metadata = _load_json_or_none(metadata_path)
        if metadata is None or not metadata.get(id_key):
            continue
        output_files = _output_files(metadata)
        records.append(
            _record(
                workflow_area=workflow_area,
                component=component,
                status=_string_or_empty(metadata.get("status")) or "READY",
                stage=stage,
                latest_artifact_id=_string_or_empty(metadata.get(id_key)) or metadata_path.parent.name,
                report_path=output_files.get(report_key, metadata_path.parent / default_report),
                metadata_path=metadata_path,
                issue_count=_int_or_zero(metadata.get("issue_count")),
                warning_count=_int_or_zero(metadata.get("warning_count")),
                error_count=_int_or_zero(metadata.get("error_count")),
                notes="",
                created_at=metadata.get("created_at"),
            )
        )
    return records


def _record(**values: Any) -> dict[str, Any]:
    row = {
        "workflow_area": "",
        "component": "",
        "status": "",
        "stage": "",
        "latest_artifact_id": "",
        "decision_date": "",
        "universe_name": "",
        "report_path": "",
        "metadata_path": "",
        "issue_count": 0,
        "warning_count": 0,
        "error_count": 0,
        "total_warning_count": 0,
        "expected_reviewable_warning_count": 0,
        "expected_demo_warning_count": 0,
        "stale_warning_count": 0,
        "actionable_warning_count": 0,
        "blocking_error_count": 0,
        "linked_snapshot_quality_status": "",
        "active_snapshot_chain": "",
        "active_snapshot_warning_count": 0,
        "active_snapshot_error_count": 0,
        "stale_snapshot_warning_count": 0,
        "unrelated_snapshot_warning_count": 0,
        "warning_classification": "",
        "next_action": "",
        "notes": "",
        "created_at": "",
    }
    row.update(values)
    component = _string_or_empty(row.get("component"))
    row["workflow_area"] = _string_or_empty(row.get("workflow_area")) or WORKFLOW_AREAS.get(component, "")
    row["status"] = _string_or_empty(row["status"]).upper()
    row["decision_date"] = _date_string(row.get("decision_date"))
    row["report_path"] = _string_or_empty(row.get("report_path"))
    row["metadata_path"] = _string_or_empty(row.get("metadata_path"))
    row["latest_artifact_id"] = _string_or_empty(row.get("latest_artifact_id"))
    row["issue_count"] = _int_or_zero(row.get("issue_count"))
    row["warning_count"] = _int_or_zero(row.get("warning_count"))
    row["error_count"] = _int_or_zero(row.get("error_count"))
    row["total_warning_count"] = _int_or_zero(row.get("total_warning_count"))
    row["expected_reviewable_warning_count"] = _int_or_zero(row.get("expected_reviewable_warning_count"))
    row["expected_demo_warning_count"] = _int_or_zero(row.get("expected_demo_warning_count"))
    row["stale_warning_count"] = _int_or_zero(row.get("stale_warning_count"))
    row["actionable_warning_count"] = _int_or_zero(row.get("actionable_warning_count"))
    row["blocking_error_count"] = _int_or_zero(row.get("blocking_error_count"))
    row["linked_snapshot_quality_status"] = _string_or_empty(row.get("linked_snapshot_quality_status"))
    row["active_snapshot_chain"] = _string_or_empty(row.get("active_snapshot_chain"))
    row["active_snapshot_warning_count"] = _int_or_zero(row.get("active_snapshot_warning_count"))
    row["active_snapshot_error_count"] = _int_or_zero(row.get("active_snapshot_error_count"))
    row["stale_snapshot_warning_count"] = _int_or_zero(row.get("stale_snapshot_warning_count"))
    row["unrelated_snapshot_warning_count"] = _int_or_zero(row.get("unrelated_snapshot_warning_count"))
    row["warning_classification"] = _string_or_empty(row.get("warning_classification"))
    return row


def _missing_dashboard_row(component: str, *, notes: str = "No matching local artifact metadata found.") -> dict[str, Any]:
    return _record(
        workflow_area=WORKFLOW_AREAS.get(component, ""),
        component=component,
        status="MISSING",
        next_action=_component_next_action(component, "MISSING"),
        notes=notes,
    )


def _component_next_action(component: str, status: str) -> str:
    if status == "FAIL":
        return "Review warnings/errors."
    if component == "HISTORICAL_BACKFILL_STATUS":
        return (
            "Run historical-backfill with a reviewed manifest in dry-run mode."
            if status == "MISSING"
            else "Review historical-backfill-status before any cache write."
        )
    if component == "MARKET_CACHE_EXPORT_POLICY_STATUS":
        return (
            "Run market-cache-export-plan with a reviewed policy request manifest."
            if status == "MISSING"
            else "Review market-cache-export-plan-status before using the generated manifest."
        )
    if component == "MARKET_CACHE_EXPORT_STATUS":
        return (
            "Run market-cache-export with a reviewed source/upstream manifest."
            if status == "MISSING"
            else "Use the reviewed cache export snapshot for current-candidates."
        )
    if component == "DATA_PREPARATION_WORKFLOW":
        return "Run data-prep-status." if status == "MISSING" else "Run current-candidates."
    if component == "SNAPSHOT_QUALITY":
        return "Run snapshot-quality." if status == "MISSING" else "Run current-candidates."
    if component == "CURRENT_CANDIDATES":
        return "Run current-candidates." if status == "MISSING" else "Run current-candidates-index."
    if component == "CURRENT_CANDIDATE_HEALTH":
        return "Run current-candidates-health." if status == "MISSING" else "Run current-to-paper."
    if component == "CURRENT_CANDIDATES_BACKFILL_PLAN_STATUS":
        return (
            "Run current-candidates-backfill-plan before multi-date candidate generation."
            if status == "MISSING"
            else "Review current-candidates-backfill-plan-status before any candidate generation."
        )
    if component == "CURRENT_CANDIDATES_BACKFILL_EXECUTION_MANIFEST_STATUS":
        return (
            "Run current-candidates-backfill-execution-manifest before preparing PIT universe overlays."
            if status == "MISSING"
            else "Review current-candidates-backfill-execution-manifest-status before any candidate generation."
        )
    if component == "PIT_UNIVERSE_OVERLAY_PLAN_STATUS":
        return (
            "Run pit-universe-overlay-plan from blocked execution manifest rows."
            if status == "MISSING"
            else "Review pit-universe-overlay-plan-status before snapshot preparation."
        )
    if component == "PIT_UNIVERSE_OVERLAY_REVIEW_STATUS":
        return (
            "Run pit-universe-overlay-review with local review evidence."
            if status == "MISSING"
            else "Review pit-universe-overlay-review-status before snapshot preparation."
        )
    if component == "PIT_UNIVERSE_EXPORT_READINESS_STATUS":
        return (
            "Run pit-universe-overlay-export-readiness from reviewed PIT universe overlay artifacts."
            if status == "MISSING"
            else "Review pit-universe-overlay-export-readiness-status before any universe export planning."
        )
    if component == "PIT_UNIVERSE_EVIDENCE_COMPLETION_HELPER_STATUS":
        return (
            "Run pit-universe-evidence-completion-helper from reviewed PIT universe overlay artifacts."
            if status == "MISSING"
            else "Review pit-universe-evidence-completion-helper-status before manual evidence updates."
        )
    if component == "PIT_UNIVERSE_EVIDENCE_REVIEW_WORKLIST_STATUS":
        return (
            "Run pit-universe-evidence-review-worklist from helper and review artifacts."
            if status == "MISSING"
            else "Review pit-universe-evidence-review-worklist-status before completed evidence update ingestion."
        )
    if component == "PIT_UNIVERSE_EVIDENCE_UPDATE_INGESTION_STATUS":
        return (
            "Run pit-universe-evidence-update-ingestion after reviewer-completed worklist updates."
            if status == "MISSING"
            else "Review clean review_updates artifact manually before a separate overlay review run."
        )
    if component == "REPLAY_SUBSTRATE_SCHEMA_FIXTURE_STATUS":
        return (
            "Run replay-substrate-schema-fixture-status."
            if status == "MISSING"
            else "Review report-only replay substrate schema fixture context; do not run real replay or training."
        )
    if component == "SOURCE_REGISTRY_SCHEMA_FIXTURE_STATUS":
        return (
            "Run source-registry-schema-fixture-status."
            if status == "MISSING"
            else "Review report-only source registry schema fixture context; do not treat rows as source permission."
        )
    if component == "COMPANY_EXPOSURE_SCHEMA_FIXTURE_STATUS":
        return (
            "Run company-exposure-schema-fixture-status."
            if status == "MISSING"
            else (
                "Review report-only company exposure schema fixture context; do not treat rows as "
                "production exposure mappings, factor observations, signal_score, or trading permission."
            )
        )
    if component == "EVENT_STRUCTURED_SCHEMA_FIXTURE_STATUS":
        return (
            "Run event-structured-schema-fixture-status."
            if status == "MISSING"
            else (
                "Review report-only event structured schema fixture context; do not treat rows as "
                "production event ingestion, active event library, factor observations, signal_score, or trading."
            )
        )
    if component == "FACTOR_OBSERVATION_SCHEMA_FIXTURE_STATUS":
        return (
            "Run factor-observation-schema-fixture-status."
            if status == "MISSING"
            else (
                "Review report-only factor observation schema fixture context; do not treat rows as real "
                "factor observations, signal_score inputs, model training inputs, active weights, active "
                "thresholds, stock_profile validation, buy-review, performance validation, or trading."
            )
        )
    if component == "REPLAY_EVIDENCE_BUNDLE_SCHEMA_FIXTURE_STATUS":
        return (
            "Run replay-evidence-bundle-schema-fixture-status."
            if status == "MISSING"
            else (
                "Review report-only replay evidence bundle schema fixture context; do not treat rows as "
                "real replay evidence bundles, replay decisions, forward labels, future labels, "
                "signal_score inputs, model training inputs, active weights, active thresholds, "
                "stock_profile validation, paper validation, buy-review, performance validation, or trading."
            )
        )
    if component == "REPLAY_DECISION_SCHEMA_FIXTURE_STATUS":
        return (
            "Run replay-decision-schema-fixture-status."
            if status == "MISSING"
            else (
                "Review report-only replay decision schema fixture context; do not treat rows as real "
                "replay decisions, real replay evidence bundle consumption, forward labels, future labels "
                "joined, signal_score inputs, model training inputs, active weights, active thresholds, "
                "stock_profile validation, paper validation, buy-review, performance validation, or trading."
            )
        )
    if component == "REVIEWED_REPLACEMENT_WORKLIST_ACTIVATION_STATUS":
        return (
            "Run reviewed-replacement-worklist-activation after acceptance planning context is reviewed."
            if status == "MISSING"
            else "Use activated replacement templates as planning context only; keep active legacy worklist unchanged."
        )
    if component == "ACTIVATED_REPLACEMENT_WORKLIST_EVIDENCE_UPDATE_PLAN_STATUS":
        return (
            "Run activated-replacement-worklist-evidence-update-plan from an activation artifact."
            if status == "MISSING"
            else "Use profile-specific evidence packages for manual evidence collection only."
        )
    if component == "ADVISORY_PROFILE_CALIBRATION_STATUS":
        return (
            "Run advisory-profile-calibration on a local candidates or scored artifact."
            if status == "MISSING"
            else "Review advisory-profile-calibration-status as calibration context only."
        )
    if component == "CALIBRATION_TO_SIGNAL_SEMANTICS_STATUS":
        return (
            "Run calibration-to-signal-semantics after advisory-profile-calibration artifacts exist."
            if status == "MISSING"
            else "Review calibration-to-signal-semantics-status as proposal context only."
        )
    if component == "SIGNAL_SEMANTICS_STATUS":
        return (
            "Run signal-semantics on a local candidates or scored artifact."
            if status == "MISSING"
            else "Review signal-semantics-status before using advisory labels."
        )
    if component == "SIGNAL_ADVISORY_STATUS":
        return (
            "Run signal-advisory from a reviewed current-candidates artifact."
            if status == "MISSING"
            else "Review signal-advisory-status before using alert previews."
        )
    if component == "SINGLE_SYMBOL_ADVISORY_STATUS":
        return (
            "Run single-symbol-advisory for a symbol and local artifact."
            if status == "MISSING"
            else "Review single-symbol-advisory-status before using the local review."
        )
    if component == "MARKET_UPDATE_HANDOFF_STATUS":
        return (
            "Run market-update-handoff for a reviewed offline update batch."
            if status == "MISSING"
            else "Run current-to-paper on the latest current-candidates artifact."
        )
    if component == "CURRENT_TO_PAPER_HANDOFF":
        return "Run current-to-paper." if status == "MISSING" else "Run current-to-paper-review."
    if component == "CURRENT_TO_PAPER_REVIEW_HANDOFF":
        return "Run current-to-paper-review." if status == "MISSING" else "Manually edit review_updates_template.csv."
    if component == "REVIEW_TEMPLATE_HEALTH":
        return "Run paper-review-template-health." if status == "MISSING" else "Run paper-review-decisions --health-check."
    if component == "PAPER_REVIEW":
        return "Run paper-review-decisions --health-check." if status == "MISSING" else "Run paper-daily --reviewed-decisions."
    if component == "DAILY_PAPER":
        return "Run paper-daily --reviewed-decisions." if status == "MISSING" else "Enter manual fills CSV."
    if component == "RECONCILIATION":
        return "Run paper-reconcile-fills." if status == "MISSING" else "Run paper-workflow-status."
    if component == "PAPER_WORKFLOW_STATUS":
        return "Run paper-workflow-status." if status == "MISSING" else "Review completed local research workflow artifacts."
    if component == "ACTIVE_REPLAY_INPUT_EMISSION_STATUS":
        return (
            "Run active-replay-input-emission after final-review emission context exists."
            if status == "MISSING"
            else "Review active-replay-input-emission-status as report-only emission context."
        )
    return ""


def _status_by_component(dashboard_frame: pd.DataFrame) -> dict[str, str]:
    frame = _finalize_dashboard_frame(dashboard_frame)
    values = {row["component"]: row["status"] for row in frame.to_dict("records")}
    for component in [*COMPONENTS, *sorted(OPTIONAL_COMPONENTS)]:
        values.setdefault(component, "MISSING")
    values.setdefault("HISTORICAL_REPLAY_INPUT_GATE_VALIDATOR_STATUS", "MISSING")
    return values


def _market_update_handoff_stage_from_frame(dashboard_frame: pd.DataFrame) -> str:
    frame = _finalize_dashboard_frame(dashboard_frame)
    rows = frame.loc[frame["component"] == "MARKET_UPDATE_HANDOFF_STATUS"]
    if rows.empty:
        return ""
    return _string_or_empty(rows.iloc[0].get("stage"))


